package org.moire.ultrasonic.service;

import android.content.Context;
import android.content.SharedPreferences;
import android.util.Log;

import org.jetbrains.annotations.NotNull;
import org.moire.ultrasonic.BuildConfig;
import org.moire.ultrasonic.api.subsonic.SubsonicAPIClient;
import org.moire.ultrasonic.api.subsonic.SubsonicAPIVersions;
import org.moire.ultrasonic.cache.Directories;
import org.moire.ultrasonic.cache.PermanentFileStorage;
import org.moire.ultrasonic.util.Constants;
import org.moire.ultrasonic.util.Util;

import java.io.File;

/**
 * @author Sindre Mehus
 * @version $Id$
 */
public class MusicServiceFactory {
    private static final String LOG_TAG = MusicServiceFactory.class.getSimpleName();
    private static MusicService REST_MUSIC_SERVICE = null;
    private static MusicService OFFLINE_MUSIC_SERVICE = null;

    public static MusicService getMusicService(Context context) {
        if (Util.isOffline(context)) {
            Log.d(LOG_TAG, "App is offline, returning offline music service.");
            if (OFFLINE_MUSIC_SERVICE == null) {
                synchronized (MusicServiceFactory.class) {
                    if (OFFLINE_MUSIC_SERVICE == null) {
                        Log.d(LOG_TAG, "Creating new offline music service");
                        OFFLINE_MUSIC_SERVICE = new OfflineMusicService(
                                createSubsonicApiClient(context),
                                getPermanentFileStorage(context));
                    }
                }
            }

            return OFFLINE_MUSIC_SERVICE;
        } else {
            Log.d(LOG_TAG, "Returning rest music service");
            if (REST_MUSIC_SERVICE == null) {
                synchronized (MusicServiceFactory.class) {
                    if (REST_MUSIC_SERVICE == null) {
                        Log.d(LOG_TAG, "Creating new rest music service");
                        REST_MUSIC_SERVICE = new CachedMusicService(new RESTMusicService(
                                createSubsonicApiClient(context),
                                getPermanentFileStorage(context)));
                    }
                }
            }

            return REST_MUSIC_SERVICE;
        }
    }

    /**
     * Resets {@link MusicService} to initial state, so on next call to {@link #getMusicService(Context)}
     * it will return updated instance of it.
     */
    public static void resetMusicService() {
        Log.d(LOG_TAG, "Resetting music service");
        synchronized (MusicServiceFactory.class) {
            REST_MUSIC_SERVICE = null;
            OFFLINE_MUSIC_SERVICE = null;
        }
    }

    private static SubsonicAPIClient createSubsonicApiClient(final Context context) {
        final SharedPreferences preferences = Util.getPreferences(context);
        int instance = preferences.getInt(Constants.PREFERENCES_KEY_SERVER_INSTANCE, 1);
        String serverUrl = preferences.getString(Constants.PREFERENCES_KEY_SERVER_URL + instance, null);
        String username = preferences.getString(Constants.PREFERENCES_KEY_USERNAME + instance, null);
        String password = preferences.getString(Constants.PREFERENCES_KEY_PASSWORD + instance, null);
        boolean allowSelfSignedCertificate = preferences
                .getBoolean(Constants.PREFERENCES_KEY_ALLOW_SELF_SIGNED_CERTIFICATE + instance, false);
        boolean enableLdapUserSupport = preferences
                .getBoolean(Constants.PREFERENCES_KEY_LDAP_SUPPORT + instance , false);

        if (serverUrl == null ||
                username == null ||
                password == null) {
            Log.i("MusicServiceFactory", "Server credentials is not available");
            return new SubsonicAPIClient("http://localhost", "", "",
                    SubsonicAPIVersions.fromApiVersion(Constants.REST_PROTOCOL_VERSION),
                    Constants.REST_CLIENT_ID, allowSelfSignedCertificate,
                    enableLdapUserSupport, BuildConfig.DEBUG);
        }

        return new SubsonicAPIClient(serverUrl, username, password,
                SubsonicAPIVersions.fromApiVersion(Constants.REST_PROTOCOL_VERSION),
                Constants.REST_CLIENT_ID, allowSelfSignedCertificate,
                enableLdapUserSupport, BuildConfig.DEBUG);
    }

    private static PermanentFileStorage getPermanentFileStorage(final Context context) {
        final SharedPreferences preferences = Util.getPreferences(context);
        int instance = preferences.getInt(Constants.PREFERENCES_KEY_SERVER_INSTANCE, 1);
        final String serverId = getServerId(preferences, instance);

        return new PermanentFileStorage(getDirectories(context), serverId, BuildConfig.DEBUG);
    }

    public static String getServerId(final SharedPreferences sp, final int instance) {
        String serverUrl = sp.getString(
                Constants.PREFERENCES_KEY_SERVER_URL + instance, null);
        return String.valueOf(Math.abs((serverUrl + instance).hashCode()));
    }

    public static Directories getDirectories(final Context context) {
        return new Directories() {
            @NotNull
            @Override
            public File getInternalCacheDir() {
                return context.getCacheDir();
            }

            @NotNull
            @Override
            public File getInternalDataDir() {
                return context.getFilesDir();
            }

            @Override
            public File getExternalCacheDir() {
                return context.getExternalCacheDir();
            }
        };
    }
}

steps.reasoning_content:
I found the issue. In `MusicServiceFactory.java`, the `createSubsonicApiClient` method reads server configuration from SharedPreferences using an `instance` index:

```java
private static SubsonicAPIClient createSubsonicApiClient(final Context context) {
    final SharedPreferences preferences = Util.getPreferences(context);
    int instance = preferences.getInt(Constants.PREFERENCES_KEY_SERVER_INSTANCE, 1);
    String serverUrl = preferences.getString(Constants.PREFERENCES_KEY_SERVER_URL + instance, null);
    String username = preferences.getString(Constants.PREFERENCES_KEY_USERNAME + instance, null);
    String password = preferences.getString(Constants.PREFERENCES_KEY_PASSWORD + instance, null);
    // ...
}
```

When the server URL or credentials are missing, it falls back to localhost defaults, and if it does find credentials, it constructs the client with the provided server URL, username, and password.

Looking at the `testConnection` method...

The issue becomes clear: when testing a connection, it sets the selected server as active via `Util.setActiveServer`, but then when `getMusicService()` creates a new `SubsonicAPIClient`, it retrieves the `instance` value from preferences using `Constants.PREFERENCES_KEY_SERVER_INSTANCE`. This preference likely defaults to `1` or doesn't reflect the server that was just set as active, causing the wrong server's URL and credentials to be used instead of the one the user just configured. The problem is becoming clear—the `instance` key is separate from the server ID being used as a suffix, so it might not stay in sync when switching between servers. I need to trace how `MusicServiceFactory.getMusicService()` is actually being called to see where this mismatch occurs. The test connection flow stores a server ID as active, but `getMusicService()` doesn't reference that stored ID at all—it just picks between REST and offline services based on connection status, completely ignoring which server should actually be used.

Looking at how the client gets initialized, it pulls a generic `instance` counter rather than the active server, so when creating a `SubsonicAPIClient` it's using the wrong server's credentials. The `createSubsonicApiClient()` method fetches preferences using this instance value, which is the root cause of the mismatch. The real problem is that `createSubsonicApiClient()` pulls from a static `instance` key rather than the active server ID that was just set, so it defaults to server 1's credentials instead of the server the user just configured. I need to make the client creation use `Util.getActiveServer(context)` to fetch the correct active server ID, just like the `testConnection` flow does when it sets the active server before calling `MusicServiceFactory.getMusicService()`. The `instance` key likely serves as a migration artifact or defaults to 1, but the real issue is that `createSubsonicApiClient()` doesn't read the active server ID that `testConnection()` sets. I need to update the method to use `Util.getActiveServer(context)` instead of relying on `Constants.PREFERENCES_KEY_SERVER_INSTANCE`.

