package org.moire.ultrasonic.util;

import android.app.Activity;
import android.app.AlertDialog;
import android.content.DialogInterface;
import android.util.Log;

import org.moire.ultrasonic.R;

/**
 * @author Sindre Mehus
 */
public abstract class ModalBackgroundTask<T> extends BackgroundTask<T>
{

	private static final String TAG = ModalBackgroundTask.class.getSimpleName();

	private final AlertDialog progressDialog;
	private Thread thread;
	private final boolean finishActivityOnCancel;
	private boolean cancelled;

	public ModalBackgroundTask(Activity activity, boolean finishActivityOnCancel)
	{
		super(activity);
		this.finishActivityOnCancel = finishActivityOnCancel;
		progressDialog = createProgressDialog();
	}

	public ModalBackgroundTask(Activity activity)
	{
		this(activity, true);
	}

	private AlertDialog createProgressDialog()
	{
		AlertDialog.Builder builder = new AlertDialog.Builder(getActivity());
		builder.setIcon(android.R.drawable.ic_dialog_info);
		builder.setTitle(R.string.background_task_wait);
		builder.setMessage(R.string.background_task_loading);
		builder.setCancelable(true);
		builder.setOnCancelListener(new DialogInterface.OnCancelListener()
		{
			@Override
			public void onCancel(DialogInterface dialogInterface)
			{
				cancel();
			}
		});
		builder.setPositiveButton(R.string.common_cancel, new DialogInterface.OnClickListener()
		{
			@Override
			public void onClick(DialogInterface dialogInterface, int i)
			{
				cancel();
			}
		});

		return builder.create();
	}

	@Override
	public void execute()
	{
		cancelled = false;
		progressDialog.show();

		thread = new Thread()
		{
			@Override
			public void run()
			{
				try
				{
					final T result = doInBackground();
					if (cancelled)
					{
						progressDialog.dismiss();
						return;
					}

					getHandler().post(new Runnable()
					{
						@Override
						public void run()
						{
							try
							{
								progressDialog.dismiss();
							}
							catch (Exception e)
							{
								// nothing
							}

							done(result);
						}
					});

				}
				catch (final Throwable t)
				{
					if (cancelled)
					{
						return;
					}
					getHandler().post(new Runnable()
					{
						@Override
						public void run()
						{
							try
							{
								progressDialog.dismiss();
							}
							catch (Exception e)
							{
								// nothing
							}

							error(t);
						}
					});
				}
			}
		};
		thread.start();
	}

	protected void cancel()
	{
		cancelled = true;
		if (thread != null)
		{
			thread.interrupt();
		}

		if (finishActivityOnCancel)
		{
			getActivity().finish();
		}
	}

	protected boolean isCancelled()
	{
		return cancelled;
	}

	@Override
	protected void error(Throwable error)
	{
		Log.w(TAG, String.format("Got exception: %s", error), error);
		new ErrorDialog(getActivity(), getErrorMessage(error), finishActivityOnCancel);
	}

	@Override
	public void updateProgress(final String message)
	{
		getHandler().post(new Runnable()
		{
			@Override
			public void run()
			{
				progressDialog.setMessage(message);
			}
		});
	}
}

package org.moire.ultrasonic.api.subsonic.interceptors

import com.fasterxml.jackson.core.JsonFactory
import com.fasterxml.jackson.core.JsonParseException
import com.fasterxml.jackson.core.JsonToken
import okhttp3.Interceptor
import okhttp3.Interceptor.Chain
import okhttp3.Response
import org.moire.ultrasonic.api.subsonic.SubsonicAPIVersions
import java.io.IOException

private const val DEFAULT_PEEK_BYTE_COUNT = 1000L

/**
 * Special [Interceptor] that adds client supported version to request and tries to update it
 * from server response.
 *
 * Optionally [notifier] will be invoked on version change.
 *
 * @author Yahor Berdnikau
 */
internal class VersionInterceptor(
        internal var protocolVersion: SubsonicAPIVersions,
        private val notifier: (SubsonicAPIVersions) -> Unit = {}) : Interceptor {
    private val jsonFactory = JsonFactory()

    override fun intercept(chain: Chain): okhttp3.Response {
        val originalRequest = chain.request()

        val newRequest = originalRequest.newBuilder()
                .url(originalRequest
                        .url()
                        .newBuilder()
                        .addQueryParameter("v", protocolVersion.restApiVersion)
                        .build())
                .build()

        val response = chain.proceed(newRequest)
        if (response.isSuccessful) {
            val isJson = response.body()?.contentType()?.subtype()?.equals("json", true) ?: false
            if (isJson) {
                tryUpdateProtocolVersion(response)
            }
        }

        return response
    }

    private fun tryUpdateProtocolVersion(response: Response) {
        val content = response.peekBody(DEFAULT_PEEK_BYTE_COUNT)
                .byteStream().bufferedReader().readText()

        try {
            val jsonReader = jsonFactory.createParser(content)
            jsonReader.nextToken()
            if (jsonReader.currentToken == JsonToken.START_OBJECT) {
                while (jsonReader.currentName != "version" &&
                        jsonReader.currentToken != null) {
                    jsonReader.nextToken()
                }
                val versionStr = jsonReader.nextTextValue()
                if (versionStr != null) {
                    try {
                        protocolVersion = SubsonicAPIVersions.fromApiVersion(versionStr)
                        notifier(protocolVersion)
                    } catch (e: IllegalArgumentException) {
                        // no-op
                    }
                }
            }
        } catch (io: IOException) {
            // no-op
        } catch (parse: JsonParseException) {
            // no-op
        }
    }
}

